import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-13';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(304, 'the-kettle-keeps-calling', 'The kettle keeps calling', 'The poem hears household appliances while the body aches. A quiet electric kettle waiting after boiling evokes the ordinary demands continuing around pain, without inventing the speaker or turning illness into spectacle.', 'Horizontal 3:2 restrained opaque gouache study of a plain cream electric kettle on a cropped practical kitchen counter, viewed from seated height. The kettle sits off-center toward right on its small base; short power cord passes behind it and exits frame naturally. Handle and spout structurally coherent, lid shut, no visible brand or lettering. A faint wisp of residual steam near spout only, no whistle hardware. A plain wall and wide quiet counter space at left, no flowers, clocks, other appliances, cup display, human or theatrical beam. Soft ordinary morning window light from outside frame; matte surfaces, selective painterly detail. Calm domestic indifference rather than a cozy product advertisement.'), (307, 'roots-that-stay', 'Roots that stay', 'The inward walker finds a deep foothold in the roots of an old tree. A low intimate view of roots entering earth carries persistence without literal lonely streets or an epic tree portrait.', 'Horizontal 3:2 broad charcoal and muted moss watercolor drawing. Close low oblique crop at the base of an ordinary mature tree; only a small portion of trunk enters at upper left. Two unequal structural roots curve into firm earth and become partly hidden, with modest soil accumulation at their contact. No exposed floating root web, heroic entire tree, foliage crown, pathway, person, ruin or bright flowers. Earth and a quiet grey-green background remain loosely indicated at right. Diffuse light, natural taper and credible branching. Charcoal weight around the foothold, spare wash elsewhere, no decorative rot, cracks or exhaustive bark microdetail. A private sense of staying grounded.'), (320, 'the-bed-of-a-village-memory', 'The bed of a village memory', 'The village poem begins in the softness of mats and a quilt, then travels through a mother’s care and remembered landscape. A modest sleeping place carries that intimate memory without fabricating the named family or combining all village imagery.', 'Horizontal 3:2 gentle colored-pencil and pale watercolor interior fragment. Oblique view of one simple woven reed sleeping mat on a plain clean earthen floor, its far end disappearing behind a softly folded lightweight cotton quilt. Muted indigo and cream quilt with subtle small running stitches, no ornate kantha motifs or invented regional pattern. Mat weave varies at selected edges, not mechanically uniform; quilt folds and compression follow gravity. Crop the mat at lower right; broad quiet dim floor at left. Low soft moonlit ambience from an unseen opening, no moon in room or theatrical beams. No bed frame, pillows arranged for styling, person, child, lamp, deity, text, decorative dust or broken wall. An affectionate ordinary resting place, memory-like but materially believable.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-13/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue13. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. No people, portraits or documentary location claims. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt)
 items.append(dict(id=ident,edition=13,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-13/{ident}/v1.png',attempts=[],medium_label={304:'gouache',307:'charcoal and watercolor',320:'colored pencil and watercolor'}[pid],independent=False))
plain=[{'poem_id': 306, 'rationale': 'The abandoned mother is a direct human question. Keep the address text-led rather than invent an elderly woman and present imagined suffering.', 'status': 'pending'}, {'poem_id': 309, 'rationale': 'The poem’s fierce metaphor for damaged forest and named hills remains in its own language; avoid literalizing sexual violence or fabricating a documentary landscape.', 'status': 'pending'}, {'poem_id': 318, 'rationale': 'The named workers and their grief require the full poem’s social context; retain a text-led opening rather than invent likenesses or dramatize the loss.', 'status': 'pending'}]
for p in (S/'content/editions/issue-13').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
